import React,{useEffect,useState} from 'react'; import { FiArrowLeft,FiArrowRight } from 'react-icons/fi'; import './Testimonials.css';
const testimonials=[{quote:'BuildWebCanada brought rare clarity to a complicated product challenge. The team is thoughtful, responsive, and genuinely invested in getting the detail right.',name:'Alex Morgan',initials:'AM',tone:'violet'},{quote:'They understood our business quickly and transformed a rough idea into a product we are genuinely proud to put in front of customers.',name:'Taylor Reed',initials:'TR',tone:'pink'},{quote:'Every step felt considered. We had visibility into the work, confidence in the decisions, and a much stronger product at the end.',name:'Jordan Blake',initials:'JB',tone:'blue'}];
const Testimonials=()=>{const [active,setActive]=useState(0);useEffect(()=>{const timer=setInterval(()=>setActive(value=>(value+1)%testimonials.length),5500);return()=>clearInterval(timer)},[]);const item=testimonials[active];const move=amount=>setActive(value=>(value+amount+testimonials.length)%testimonials.length);return <section className="testimonials-section"><div className="testimonial-header"><div><span className="mini-rule"/><p className="section-kicker">Client perspective</p></div><h2>Built on trust.<br/><b>Proven in the work.</b></h2></div><div className="testimonial-stage" aria-live="polite"><div className={`quote-mark ${item.tone}`}>“</div><blockquote key={active}><p>{item.quote}</p><footer><span className={`person-avatar ${item.tone}`}>{item.initials}</span><span><strong>{item.name}</strong></span></footer></blockquote><div className="testimonial-controls"><button aria-label="Previous testimonial" onClick={()=>move(-1)}><FiArrowLeft/></button><div>{testimonials.map((entry,index)=><button key={entry.name} aria-label={`Show testimonial from ${entry.name}`} className={active===index?'active':''} onClick={()=>setActive(index)}/>)}</div><button aria-label="Next testimonial" onClick={()=>move(1)}><FiArrowRight/></button></div></div></section>};
export default Testimonials;
